using System.Buffers;
using System.ComponentModel;
using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Text;

using Wren.Native;

namespace Wren;

/// <summary>Helpers for code generated by Wren.SourceGenerator.</summary>
[EditorBrowsable(EditorBrowsableState.Never)]
public static unsafe class WrenRuntime
{
    private const int MaxStackString = 512;

    [ThreadStatic] private static int s_ForeignDepth;

    #region Foreign calls

    public static bool IsInForeignCall => s_ForeignDepth > 0;

    public static void EnterForeign() => s_ForeignDepth++;

    public static void ExitForeign() => s_ForeignDepth--;

    // Exceptions must not unwind through native Wren code, so they become a fiber abort.
    public static void Abort(nint vm, string label, Exception exception)
    {
        SetString(vm, 0, label + ": " + exception.GetType().Name + ": " + exception.Message);
        WrenApi.AbortFiber(vm, 0);
    }

    #endregion

    #region Strings

    public static string GetString(nint vm, int slot)
    {
        int length;
        var bytes = WrenApi.GetSlotBytes(vm, slot, &length);
        return Encoding.UTF8.GetString(bytes, length);
    }

    public static void SetString(nint vm, int slot, string? value)
    {
        if (value is null)
        {
            WrenApi.SetSlotNull(vm, slot);
            return;
        }

        var maxLength = Encoding.UTF8.GetMaxByteCount(value.Length);
        byte[]? rented = null;

        // At least one byte so the pointer is never null, even for "" (Wren asserts).
        Span<byte> buffer = maxLength <= MaxStackString
            ? stackalloc byte[MaxStackString]
            : rented = ArrayPool<byte>.Shared.Rent(maxLength);

        try
        {
            var length = Encoding.UTF8.GetBytes(value, buffer);
            fixed (byte* bytes = buffer)
                WrenApi.SetSlotBytes(vm, slot, bytes, (nuint)length);
        }
        finally
        {
            if (rented is not null)
                ArrayPool<byte>.Shared.Return(rented);
        }
    }

    public static char GetChar(nint vm, int slot, string name)
    {
        var value = GetString(vm, slot);
        return value.Length == 1
            ? value[0]
            : throw new ArgumentException($"Expected a single character for argument '{name}', got \"{value}\".");
    }

    #endregion

    #region Foreign objects

    public static T GetObject<T>(nint vm, int slot)
    {
        var data = (nint*)WrenApi.GetSlotForeign(vm, slot);
        return (T)GCHandle.FromIntPtr(*data).Target!;
    }

    public static ref T GetRef<T>(nint vm, int slot) where T : struct
    {
        var data = (nint*)WrenApi.GetSlotForeign(vm, slot);
        return ref Unsafe.Unbox<T>(GCHandle.FromIntPtr(*data).Target!);
    }

    public static bool IsObject<T>(nint vm, int slot)
    {
        if (WrenApi.GetSlotType(vm, slot) != WrenType.Foreign)
            return false;

        var data = (nint*)WrenApi.GetSlotForeign(vm, slot);
        return *data != 0 && GCHandle.FromIntPtr(*data).Target is T;
    }

    public static void NewObject(nint vm, int slot, int classSlot, object value)
    {
        var data = (nint*)WrenApi.SetSlotNewForeign(vm, slot, classSlot, (nuint)sizeof(nint));
        *data = GCHandle.ToIntPtr(GCHandle.Alloc(value));
    }

    public static void GetClass(nint vm, string module, string className, int slot)
      => WrenVm.FromNative(vm).LoadClass(module, className, slot);

    public static nint Finalizer => (nint)(delegate* unmanaged[Cdecl]<nint, void>)&FreeObject;

    [UnmanagedCallersOnly(CallConvs = [typeof(CallConvCdecl)])]
    private static void FreeObject(nint data)
    {
        var handle = *(nint*)data;
        if (handle == 0)
            return;

        *(nint*)data = 0;
        GCHandle.FromIntPtr(handle).Free();
    }

    #endregion

    #region Lists and maps

    // Elements go through `freeSlot` and the slots after it, which the generated Wren code reserves by passing extra
    // arguments. Don't call wrenEnsureSlots in a foreign method: it can reallocate the fiber stack under the
    // interpreter, and in an allocator it changes which value Wren takes as the new object.

    public static List<T> GetList<T>(nint vm, int slot, int freeSlot, SlotReader<T> read)
    {
        var count = WrenApi.GetListCount(vm, slot);
        var list = new List<T>(count);

        for (var i = 0; i < count; i++)
        {
            WrenApi.GetListElement(vm, slot, i, freeSlot);
            list.Add(read(vm, freeSlot, freeSlot + 1));
        }

        return list;
    }

    public static T[] GetArray<T>(nint vm, int slot, int freeSlot, SlotReader<T> read)
    {
        var array = new T[WrenApi.GetListCount(vm, slot)];

        for (var i = 0; i < array.Length; i++)
        {
            WrenApi.GetListElement(vm, slot, i, freeSlot);
            array[i] = read(vm, freeSlot, freeSlot + 1);
        }

        return array;
    }

    // Wren's API can't list a map's keys, so the generated Wren code passes them as a list in keysSlot.
    public static Dictionary<TKey, TValue> GetMap<TKey, TValue>(nint vm, int mapSlot, int keysSlot, int freeSlot,
        SlotReader<TKey> readKey, SlotReader<TValue> readValue) where TKey : notnull
    {
        var count = WrenApi.GetListCount(vm, keysSlot);
        var map = new Dictionary<TKey, TValue>(count);

        for (var i = 0; i < count; i++)
        {
            WrenApi.GetListElement(vm, keysSlot, i, freeSlot);
            WrenApi.GetMapValue(vm, mapSlot, freeSlot, freeSlot + 1);
            map[readKey(vm, freeSlot, freeSlot + 2)] = readValue(vm, freeSlot + 1, freeSlot + 2);
        }

        return map;
    }

    public static void SetList<T>(nint vm, int slot, int freeSlot, IEnumerable<T> values, SlotWriter<T> write)
    {
        WrenApi.SetSlotNewList(vm, slot);

        foreach (var value in values)
        {
            write(vm, freeSlot, freeSlot + 1, value);
            WrenApi.InsertInList(vm, slot, -1, freeSlot);
        }
    }

    public static void SetMap<TKey, TValue>(nint vm, int slot, int freeSlot,
        IEnumerable<KeyValuePair<TKey, TValue>> values, SlotWriter<TKey> writeKey, SlotWriter<TValue> writeValue)
    {
        WrenApi.SetSlotNewMap(vm, slot);

        foreach (var pair in values)
        {
            writeKey(vm, freeSlot, freeSlot + 2, pair.Key);
            writeValue(vm, freeSlot + 1, freeSlot + 2, pair.Value);
            WrenApi.SetMapValue(vm, slot, freeSlot, freeSlot + 1);
        }
    }

    #endregion

    public static T ToNumber<T>(double value, string name) where T : INumberBase<T>
    {
        try
        {
            return T.CreateChecked(value);
        }
        catch (OverflowException)
        {
            throw new ArgumentOutOfRangeException(name, value, $"Argument '{name}' doesn't fit in {typeof(T).Name}.");
        }
    }

    public static Exception NullArgument(string name)
      => new ArgumentNullException(name, $"Argument '{name}' can't be null.");

    public static Exception WrongArgumentType(string name, WrenType expected, WrenType actual)
      => new ArgumentException($"Expected {expected} for argument '{name}', got {actual}.");
}

[EditorBrowsable(EditorBrowsableState.Never)]
public delegate T SlotReader<out T>(nint vm, int slot, int freeSlot);

[EditorBrowsable(EditorBrowsableState.Never)]
public delegate void SlotWriter<in T>(nint vm, int slot, int freeSlot, T value);
